def _key(a, b): return "-".join(sorted([a, b]))

def meaning(pair, aspect):
    a, b = pair.split("-")
    return (f"Composite {BARE[a]}: {PLANET_MEANING[a]}. Composite {BARE[b]}: {PLANET_MEANING[b]}. "
            f"{ASPECT_NOUN[aspect]}: {ASPECT_MEANING[aspect]}.")

def has_lived(pair, aspect, rel_type):
    return rel_type in LIVED.get(pair, {}).get(VALENCE[aspect], {})

def compose_typed(a, b, aspect, rel_type):
    """Compose one composite-aspect reading for a specific relationship type.
    Returns None if the lived layer for this (pair, valence, type) is not authored yet."""
    pair = _key(a, b); A, B = pair.split("-"); val = VALENCE[aspect]
    lived = LIVED.get(pair, {}).get(val, {}).get(rel_type)
    if lived is None:
        return None
    astro = f"your composite {BARE[A]} {ASPECT_VERB[aspect]} your composite {BARE[B]}"
    return {"title": f"Composite {BARE[A]} {ASPECT_WORD[aspect]} {BARE[B]}",
            "relationshipType": rel_type, "typeLabel": LABELS[rel_type],
            "meaning": meaning(pair, aspect),
            "paragraphs": [lived["experience"], lived["advice"], f"The astro: {astro}."],
            "eyebrow": {"label": "Composite aspect", "pair": pair, "aspect": aspect,
                        "valence": val, "relationshipType": rel_type},
            "astro": astro,
            "trace": {"pair": pair, "aspect": aspect, "relationshipType": rel_type,
                      "sourceKeys": [f"cc/composite/{A}", f"cc/composite/{B}"],
                      "readerAuthority": "composed-reviewed"}}
